--- /dev/null
+++ b/internal/gateway/metrics.go
@@ -0,0 +1,32 @@
+package gateway
+
+const (
+	httpErrorsMetricName = "gateway_http_errors_total"
+	httpErrorsMetricHelp = "Total number of HTTP responses with a 4xx or 5xx status code."
+)
+
+type metricCounter interface {
+	Inc()
+}
+
+// metricRegistry creates and registers counters in the application's metrics
+// registry.
+type metricRegistry interface {
+	NewCounter(name, help string) metricCounter
+}
+
+type gatewayMetrics struct {
+	httpErrors metricCounter
+}
+
+func registerGatewayMetrics(registry metricRegistry) gatewayMetrics {
+	return gatewayMetrics{
+		httpErrors: registry.NewCounter(httpErrorsMetricName, httpErrorsMetricHelp),
+	}
+}
+
+func (m gatewayMetrics) recordHTTPResponse(statusCode int) {
+	if statusCode >= 400 && statusCode < 600 {
+		m.httpErrors.Inc()
+	}
+}
