+++ b/internal/gateway/metrics_test.go
@@ -0,0 +1,56 @@
+package gateway
+
+import "testing"
+
+type testCounter struct {
+	value int
+}
+
+func (c *testCounter) Inc() {
+	c.value++
+}
+
+type testRegistry struct {
+	name    string
+	help    string
+	counter *testCounter
+}
+
+func (r *testRegistry) NewCounter(name, help string) metricCounter {
+	r.name = name
+	r.help = help
+	r.counter = &testCounter{}
+	return r.counter
+}
+
+func TestRegisterGatewayMetrics(t *testing.T) {
+	registry := &testRegistry{}
+
+	registerGatewayMetrics(registry)
+
+	if registry.name != httpErrorsMetricName {
+		t.Fatalf("registered metric name = %q, want %q", registry.name, httpErrorsMetricName)
+	}
+	if registry.help != httpErrorsMetricHelp {
+		t.Fatalf("registered metric help = %q, want %q", registry.help, httpErrorsMetricHelp)
+	}
+}
+
+func TestRecordHTTPResponse(t *testing.T) {
+	registry := &testRegistry{}
+	metrics := registerGatewayMetrics(registry)
+
+	for _, statusCode := range []int{100, 200, 301, 399, 600} {
+		metrics.recordHTTPResponse(statusCode)
+	}
+	if registry.counter.value != 0 {
+		t.Fatalf("counter after non-error responses = %d, want 0", registry.counter.value)
+	}
+
+	for _, statusCode := range []int{400, 404, 499, 500, 503, 599} {
+		metrics.recordHTTPResponse(statusCode)
+	}
+	if registry.counter.value != 6 {
+		t.Fatalf("counter after error responses = %d, want 6", registry.counter.value)
+	}
+}
